function C = colocConformanceCases()
%COLOCCONFORMANCECASES  Synthetic two-channel images with known colocalisation.
%
%   C = colocConformanceCases()
%
% Returns a struct array, one element per case, used by
% testColocConformance (analytical answers) and by fixtures/makeColocGolden
% (written as TIFFs and run through Fiji Coloc 2 for golden values). Every
% image is uint8 and integer valued, so Coloc 2's Costes stepper (one grey
% level per step) and our exact per-pixel walk see the same intensities.
% Deterministic: fixed rng seeds, so the TIFFs in fixtures/images can be
% regenerated byte for byte.
%
% Fields
%   name   case name (TIFF file stem)
%   ch1    [128 128] uint8
%   ch2    [128 128] uint8
%   what   one-line description
%   sigA   (partial overlap only) logical, channel 1 signal region
%   sigB   (partial overlap only) logical, channel 2 signal region
%
% Cases
%   identical      ch2 = ch1 (blobs on a noisy background): r = 1, M1 = M2 = 1
%   independent    two independently generated blob images: r ~ 0
%   anticorrelated ch2 = 255 - ch1: r = -1, no positive regression slope
%   partialOverlap uniform-intensity squares A (ch1) and B (ch2) on a zero
%                  background, A and B overlapping by exactly half: M1 = M2 = 0.5
%   costesClassic  dim independent background (0-40) everywhere plus a
%                  bright, correlated signal block (80-200): Costes' own
%                  textbook situation; thresholds fall below the signal band
%   partialNoisy   partialOverlap with independent background noise (golden only)

sz = [128 128];
C = struct('name', {}, 'ch1', {}, 'ch2', {}, 'what', {}, 'sigA', {}, 'sigB', {});

% --- identical -------------------------------------------------------------
rng(101);
a = blobs(sz);
C(end+1) = mk('identical', a, a, 'ch2 = ch1', [], []);

% --- independent -----------------------------------------------------------
rng(102);
a = blobs(sz);
b = blobs(sz);
C(end+1) = mk('independent', a, b, 'independent blob images', [], []);

% --- anticorrelated --------------------------------------------------------
rng(103);
a = blobs(sz);
C(end+1) = mk('anticorrelated', a, 255 - a, 'ch2 = 255 - ch1', [], []);

% --- partialOverlap (noise-free) -------------------------------------------
sigA = false(sz);
sigB = false(sz);
sigA(33:96, 17:80) = true;     % 64 x 64
sigB(33:96, 49:112) = true;    % 64 x 64, shifted 32 columns: half of each overlaps
a = uint8(150 * sigA);
b = uint8(100 * sigB);
C(end+1) = mk('partialOverlap', a, b, 'squares overlapping by half, zero background', sigA, sigB);

% --- partialNoisy ----------------------------------------------------------
rng(105);
a = uint8(round(150 * sigA + 10 + 8 * rand(sz)));
b = uint8(round(100 * sigB + 10 + 8 * rand(sz)));
C(end+1) = mk('partialNoisy', a, b, 'partialOverlap plus independent background 10-18', sigA, sigB);

% --- costesClassic ---------------------------------------------------------
rng(104);
a = 40 * rand(sz);
b = 40 * rand(sz);
blk = false(sz);
blk(41:88, 41:88) = true;
s = 80 + 120 * rand(nnz(blk), 1);
a(blk) = s;
b(blk) = 0.8 * s + 10 + 4 * randn(nnz(blk), 1);
C(end+1) = mk('costesClassic', uint8(round(a)), uint8(round(b)), ...
    'independent background 0-40 + correlated block 80-200', blk, blk);

end

function c = mk(name, ch1, ch2, what, sigA, sigB)
c = struct('name', name, 'ch1', uint8(ch1), 'ch2', uint8(ch2), 'what', what, ...
    'sigA', sigA, 'sigB', sigB);
end

function im = blobs(sz)
% Gaussian blobs (about PSF size) at random positions on a noisy background,
% integer valued 0-255.
im = zeros(sz);
n = 60;
r = randi(sz(1), n, 1);
c = randi(sz(2), n, 1);
im(sub2ind(sz, r, c)) = 1;
im = imgaussfilt(im, 2.5);
im = im / max(im(:));
im = round(20 + 200 * im + 10 * rand(sz));
im = min(max(im, 0), 255);
end
